#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=9

GH_REPO="Evilperson1337/requestarr"
GH_OWNER="Evilperson1337"
IMAGE="ghcr.io/evilperson1337/requestarr"   # GHCR names are lower-case
TEMPLATE_URL="https://raw.githubusercontent.com/evilperson1337/requestarr/main/deploy/unraid/requestarr.xml"

cd "$(dirname "${BASH_SOURCE[0]}")/.."
REPO_ROOT="$PWD"
TICKET="$REPO_ROOT/.scratch/unraid-deployment/issues/08-publish-rc-and-test-on-unraid.md"

# Answers are remembered in a state file OUTSIDE the repo, so the app's own .env is never touched.
# Assigned outright: the library above defaults ENV_FILE to ".env", which must not be used here.
ENV_FILE="${WIZARD_STATE_FILE:-${XDG_STATE_HOME:-$HOME/.local/state}/requestarr/publish-release.env}"
mkdir -p "$(dirname "$ENV_FILE")"
[[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")

PUBLISH_CHECKS=()   # one line per automated check of the published image, for the ticket

# anon_manifest_status TAG prints the HTTP status of an anonymous manifest request,
# which is what Unraid's pull sees. 200 means the package is public and the tag exists.
anon_manifest_status() {
  local tag="$1" repo="${IMAGE#ghcr.io/}" token=""
  token=$(curl -fsS "https://ghcr.io/token?scope=repository:${repo}:pull" 2>/dev/null \
    | python3 -c 'import sys, json; print(json.load(sys.stdin).get("token", ""))' 2>/dev/null) || token=""
  curl -s -o /dev/null -w '%{http_code}' \
    -H "Authorization: Bearer $token" \
    -H 'Accept: application/vnd.oci.image.index.v1+json, application/vnd.docker.distribution.manifest.list.v2+json, application/vnd.oci.image.manifest.v1+json' \
    "https://ghcr.io/v2/${repo}/manifests/${tag}" || true
}

# find_run waits up to $1 seconds for the release workflow run of $RELEASE_TAG and prints its id.
find_run() {
  local waited=0 id=""
  while ((waited < $1)); do
    id=$(gh run list -R "$GH_REPO" --workflow release.yml --limit 5 --json databaseId,headBranch \
      --jq "map(select(.headBranch==\"$RELEASE_TAG\"))[0].databaseId // empty" 2>/dev/null || true)
    [[ -n "$id" ]] && { printf '%s' "$id"; return 0; }
    sleep 4; waited=$((waited + 4))
  done
  return 1
}

# gh_push runs git with gh's login for this one command; no global git config is changed.
gh_push() {
  GIT_CONFIG_COUNT=2 \
    GIT_CONFIG_KEY_0=credential.helper GIT_CONFIG_VALUE_0= \
    GIT_CONFIG_KEY_1=credential.helper GIT_CONFIG_VALUE_1='!gh auth git-credential' \
    git -C "$EXPORT_DIR" push "https://github.com/$GH_REPO.git" "$@"
}

stage_1() {
  stage "Preflight: tools, GitHub login and what will be released"
  local need=() t
  for t in git gh docker python3 curl; do
    command -v "$t" >/dev/null 2>&1 || need+=("$t")
  done
  if ((${#need[@]})); then
    warn "missing tools: ${need[*]}"
    say "Install them, then run this wizard again."
    exit 1
  fi

  have_filter_repo() { { [[ -n "${GIT_FILTER_REPO:-}" ]] && [[ -x "$GIT_FILTER_REPO" ]]; } || command -v git-filter-repo >/dev/null 2>&1; }
  until have_filter_repo; do
    warn "git-filter-repo is not installed. The export needs it."
    step "Arch / CachyOS:  sudo pacman -S git-filter-repo"
    step "Anything else:   pipx install git-filter-repo   (or: pip install --user git-filter-repo)"
    pause "Install it, then press Enter to check again (Ctrl-C to stop)"
  done
  say "✓ git-filter-repo found"

  gh_ready() {
    gh auth status >/dev/null 2>&1 || return 1
    local scopes; scopes=$(gh auth status 2>&1 | grep -i 'token scopes' || true)
    [[ "$scopes" == *"'repo'"* && "$scopes" == *"'workflow'"* ]]
  }
  until gh_ready; do
    warn "gh is not logged in, or its token lacks the 'repo' and 'workflow' scopes."
    step "Run:  gh auth refresh -h github.com -s repo,workflow    (or: gh auth login)"
    pause "Do that, then press Enter to check again (Ctrl-C to stop)"
  done
  local login; login=$(gh api user --jq .login 2>/dev/null || true)
  say "✓ gh is logged in as ${login:-unknown} with repo and workflow scopes"
  if [[ -n "$login" && "${login,,}" != "${GH_OWNER,,}" ]]; then
    warn "You are logged in as $login, but the public repository belongs to $GH_OWNER."
    confirm "Continue anyway?" || exit 1
  fi

  say ""
  say "Source repository: $REPO_ROOT"
  say "Branch:            $(git branch --show-current)"
  say "Release commit:    $(git log -1 --format='%h %s')"
  if [[ -n "$(git status --porcelain --untracked-files=no)" ]]; then
    warn "You have uncommitted changes. Only committed work is released."
    confirm "Continue without them?" || exit 1
  fi
  note "The export publishes this commit as the public 'main'."
  confirm "Release this commit?" || exit 1

  while :; do
    ask RELEASE_TAG "Release tag (Enter for v0.1.0-rc.4):" || exit 1
    [[ -n "$RELEASE_TAG" ]] || RELEASE_TAG="v0.1.0-rc.4"
    [[ "$RELEASE_TAG" =~ ^v[0-9]+\.[0-9]+\.[0-9]+(-[0-9A-Za-z.]+)?$ ]] && break
    warn "A tag looks like v0.1.0 or v0.1.0-rc.1."
  done
  write_env RELEASE_TAG "$RELEASE_TAG"
  if [[ "$RELEASE_TAG" == *-* ]]; then
    note "Pre-release: the image gets only the exact tag. 'latest' and the short vX.Y tag do not move."
  else
    note "Stable release: 'latest' and the short vX.Y tag move to this image."
  fi
}

stage_2() {
  stage "GitHub: the public repository"
  local vis
  if gh repo view "$GH_REPO" >/dev/null 2>&1; then
    vis=$(gh repo view "$GH_REPO" --json visibility --jq .visibility)
    say "$GH_REPO already exists ($vis)."
    [[ "$vis" == "PUBLIC" ]] || warn "It is not public. The image and template links need a public repository."
    if gh api "repos/$GH_REPO/commits?per_page=1" >/dev/null 2>&1; then
      note "It already has commits. The push never forces, so it only works if they are an ancestor of this export."
    fi
  else
    say "$GH_REPO does not exist yet."
    say "It will be created public and empty (no README, licence or .gitignore), so the exported history is pushed as it is."
    confirm "Create the public repository $GH_REPO now?" || exit 1
    gh repo create "$GH_REPO" --public \
      --description "A shared request, availability and notification portal for movies, TV, music, games and audiobooks." >/dev/null
    say "✓ created"
  fi
  open_url "https://github.com/$GH_REPO"
}

stage_3() {
  stage "Tag the release and export the scrubbed copy"
  local tagged
  if git rev-parse -q --verify "refs/tags/$RELEASE_TAG" >/dev/null; then
    tagged=$(git rev-list -n1 "$RELEASE_TAG")
    if [[ "$tagged" == "$(git rev-parse HEAD)" ]]; then
      say "Tag $RELEASE_TAG already exists at this commit."
    else
      warn "Tag $RELEASE_TAG exists, but at a different commit ($(git rev-parse --short "$tagged"))."
      confirm "Export anyway, with the tag where it is?" || exit 1
    fi
  else
    confirm "Create the annotated tag $RELEASE_TAG at $(git rev-parse --short HEAD) in this repository?" || exit 1
    git tag -a "$RELEASE_TAG" -m "Requestarr $RELEASE_TAG"
    say "✓ tagged"
  fi
  if git remote get-url origin >/dev/null 2>&1 && confirm "Also push the tag to your origin remote?"; then
    git push origin "refs/tags/$RELEASE_TAG"
  fi

  EXPORT_DIR="${TMPDIR:-/tmp}/requestarr-public-export-$RELEASE_TAG"
  if [[ -e "$EXPORT_DIR" ]]; then
    warn "$EXPORT_DIR exists from an earlier run."
    confirm "Delete it and export again?" || exit 1
    rm -rf -- "$EXPORT_DIR"   # a fixed prefix plus the validated tag
  fi
  write_env EXPORT_DIR "$EXPORT_DIR"

  say ""
  say "Exporting: rewriting the whole history and running the gate. This takes a minute."
  if ! "$REPO_ROOT/scripts/export-public.sh" "$RELEASE_TAG" "$EXPORT_DIR"; then
    warn "The export failed or the gate found something. Nothing was written and nothing has left your machine."
    say "Copy the message above to Claude."
    exit 1
  fi
  say "✓ gate passed: no trace of the private domain in any ref, message, author, path or file"
  say "Commits:     $(git -C "$EXPORT_DIR" rev-list --count main)"
  say "Module path: $(head -1 "$EXPORT_DIR/go.mod")"
  say "Tags:        $(git -C "$EXPORT_DIR" tag --list | tr '\n' ' ')"
  say "Authors:"
  git -C "$EXPORT_DIR" log --format='%an <%ae>' main | sort | uniq -c | sed 's/^/    /'
  say ""
  confirm "Does this look right? Nothing has left your machine yet." || exit 1
}

stage_4() {
  stage "Push to GitHub (this makes the code public)"
  say "This pushes main, then the tags to https://github.com/$GH_REPO, each as its own push."
  say "The $RELEASE_TAG tag goes last and alone: that is what starts the release workflow"
  say "(image build, signing, attestation). GitHub starts nothing for a tag pushed together with a branch."
  say "Other version tags are not published. It never forces, and it re-runs the gate first."
  confirm "Push now?" || exit 1
  GIT_CONFIG_COUNT=2 \
    GIT_CONFIG_KEY_0=credential.helper GIT_CONFIG_VALUE_0= \
    GIT_CONFIG_KEY_1=credential.helper GIT_CONFIG_VALUE_1='!gh auth git-credential' \
    "$REPO_ROOT/scripts/publish-public.sh" "$EXPORT_DIR" "https://github.com/$GH_REPO.git" "$RELEASE_TAG"
  say "✓ pushed"
}

stage_5() {
  stage "Watch the release workflow"
  open_url "https://github.com/$GH_REPO/actions"
  say "Waiting for the run for $RELEASE_TAG to appear..."
  local run_id=""
  run_id=$(find_run 120) || run_id=""
  if [[ -z "$run_id" ]]; then
    warn "No run appeared after two minutes."
    say "Tags on GitHub: $(gh api "repos/$GH_REPO/tags" --jq '[.[].name] | join(", ")' 2>/dev/null || echo unknown)"
    say "Runs so far:    $(gh api "repos/$GH_REPO/actions/runs" --jq .total_count 2>/dev/null || echo unknown)"
    note "A tag pushed in the same push as a branch can be dropped by GitHub, so no workflow starts."
    say "Fix: delete the tag on GitHub and push it again on its own. That is safe: it is the same tag object."
    if confirm "Re-push $RELEASE_TAG alone now?"; then
      gh_push ":refs/tags/$RELEASE_TAG"
      gh_push "refs/tags/$RELEASE_TAG"
      say "Waiting for the run..."
      run_id=$(find_run 90) || run_id=""
    fi
    if [[ -z "$run_id" ]]; then
      warn "Still no run. Check the Actions page: workflows may be disabled for the repository or the account."
      say "Copy what you see to Claude."
      exit 1
    fi
  fi
  write_env RUN_URL "https://github.com/$GH_REPO/actions/runs/$run_id"
  say "Run: $RUN_URL"
  if gh run watch "$run_id" -R "$GH_REPO" --exit-status; then
    say "✓ the release workflow succeeded"
  else
    warn "The release workflow failed. Last lines of the failing steps:"
    gh run view "$run_id" -R "$GH_REPO" --log-failed 2>/dev/null | tail -n 80 || true
    say ""
    say "Copy the lines above to Claude. The fix is made in your private repository, and then you run"
    say "this wizard again with a new tag (for example the next release candidate, v0.1.0-rc.2)."
    exit 1
  fi
}

stage_6() {
  stage "Make the container image public"
  say "A package published by a workflow starts out private on GitHub. Unraid pulls anonymously, so it must be public."
  open_url "https://github.com/users/$GH_OWNER/packages/container/requestarr/settings"
  step "Scroll to the Danger Zone, click Change package visibility, choose Public."
  step "Type the package name (requestarr) to confirm."
  pause "Press Enter once you have done that"
  while [[ "$(anon_manifest_status "$RELEASE_TAG")" != "200" ]]; do
    warn "An anonymous request for $IMAGE:$RELEASE_TAG did not succeed."
    note "It can take a minute to apply. If the tag is wrong, the workflow may not have pushed it."
    confirm "Test again?" || { warn "Continuing without a working anonymous pull."; break; }
  done
  [[ "$(anon_manifest_status "$RELEASE_TAG")" == "200" ]] && say "✓ anonymous pull works for $RELEASE_TAG"
}

stage_7() {
  stage "Verify the published image"
  local inspect digest platforms status short att t
  inspect=$(docker buildx imagetools inspect "$IMAGE:$RELEASE_TAG" 2>&1 || true)
  digest=$(printf '%s\n' "$inspect" | awk '/^Digest:/ {print $2; exit}')
  platforms=$(printf '%s\n' "$inspect" | awk '/Platform:/ {print $2}' | sort -u | tr '\n' ' ')
  if [[ -n "$digest" ]]; then
    write_env IMAGE_DIGEST "$digest"
    say "Digest: $digest"
  else
    warn "Could not read the image from the registry."
  fi
  if [[ "$platforms" == *linux/amd64* && "$platforms" == *linux/arm64* ]]; then
    say "✓ platforms: $platforms"; PUBLISH_CHECKS+=("platforms: linux/amd64 and linux/arm64")
  else
    warn "Expected linux/amd64 and linux/arm64, found: ${platforms:-none}"; PUBLISH_CHECKS+=("platforms: FAILED, found ${platforms:-none}")
  fi

  short=$(printf '%s' "${RELEASE_TAG%%-*}" | cut -d. -f1,2)   # v0.1.0 and v0.1.0-rc.1 both give v0.1
  if [[ "$RELEASE_TAG" == *-* ]]; then
    for t in latest "$short"; do
      status=$(anon_manifest_status "$t")
      if [[ "$status" != "200" ]]; then
        say "✓ tag '$t' does not exist (a pre-release must not move it)"; PUBLISH_CHECKS+=("tag $t not moved by the pre-release")
      else
        warn "Tag '$t' exists and a pre-release should not have moved it."; PUBLISH_CHECKS+=("tag $t: FAILED, it exists")
      fi
    done
  else
    for t in latest "$short"; do
      status=$(anon_manifest_status "$t")
      if [[ "$status" == "200" ]]; then say "✓ tag '$t' exists"; PUBLISH_CHECKS+=("tag $t moved to this release")
      else warn "Tag '$t' is missing (HTTP $status)."; PUBLISH_CHECKS+=("tag $t: FAILED, HTTP $status"); fi
    done
  fi

  say ""
  if att=$(gh attestation verify "oci://$IMAGE:$RELEASE_TAG" --repo "$GH_REPO" 2>&1); then
    say "✓ build-provenance attestation verifies"; PUBLISH_CHECKS+=("provenance attestation verifies")
  else
    warn "Attestation check failed:"; printf '%s\n' "$att" | tail -n 8 | sed 's/^/    /'
    PUBLISH_CHECKS+=("provenance attestation: FAILED")
  fi

  if command -v cosign >/dev/null 2>&1; then
    if cosign verify "$IMAGE:$RELEASE_TAG" \
        --certificate-identity-regexp "^https://github.com/${GH_REPO,,}/\\.github/workflows/release\\.yml@refs/tags/v" \
        --certificate-oidc-issuer https://token.actions.githubusercontent.com >/dev/null 2>&1; then
      say "✓ cosign signature verifies"; PUBLISH_CHECKS+=("cosign signature verifies")
    else
      warn "cosign verify failed."; PUBLISH_CHECKS+=("cosign signature: FAILED")
    fi
  else
    SKIPPED+=("cosign signature check: install cosign and run the command in docs/RELEASES.md ('Verifying a release image')")
    PUBLISH_CHECKS+=("cosign signature: not checked (cosign not installed)")
    note "cosign is not installed, so the signature check is left for you (see the summary)."
  fi
  write_env PUBLISH_CHECKS "$(IFS='|'; printf '%s' "${PUBLISH_CHECKS[*]}")"
  say ""
  pause "Press Enter to go on to the Unraid test"
}

stage_8() {
  stage "Test on your Unraid server"
  say "Two passes: (A) the compose file pinned to $RELEASE_TAG, then (B) the template."
  open_url "https://github.com/$GH_REPO/blob/main/docs/UNRAID.md"
  step "Follow the guide for the prerequisites: PostgreSQL, a TLS reverse proxy (a Keycloak client comes after the first sign-in)."
  step "Pass A: copy deploy/unraid/ to the server, fill in requestarr.env, set REQUESTARR_TAG=$RELEASE_TAG, run docker compose up -d."
  step "Pass B: Docker tab, Template Repositories, add:"
  say  "      $TEMPLATE_URL"
  step "then Add Container, choose Requestarr, fill the fields, use a user-defined network."
  note "The checklist is docs/MANUAL_TESTING.md section 14. Take your time: you can stop and come back with WIZARD_FROM=8."
  pause "Press Enter when you have results to record"

  local titles=(
    "Compose pass A: container healthy and the local administrator signs in"
    "Install from the Template Repositories URL (icon, link, pinned tag, image pulls)"
    "Healthy container (unhealthy when PostgreSQL stops, recovers when it starts)"
    "Bad configuration reported (http public URL, malformed master key)"
    "Local administrator sign-in, OIDC set up in Settings and tested; an OIDC person is a viewer until promoted"
    "Library over a private http:// address syncs; a public http:// name is rejected"
    "Master key separation (restore with a different key does not crash)"
  )
  local i n answer result_var note_var
  for i in "${!titles[@]}"; do
    n=$((i + 1)); result_var="RESULT_$n"; note_var="NOTE_$n"
    while :; do
      ask "$result_var" "$n. ${titles[$i]}  [pass/fail/skip]:" || exit 1
      answer="${!result_var}"
      case "$answer" in pass|fail|skip) break ;; esac
      warn "Type pass, fail or skip."
    done
    write_env "$result_var" "$answer"
    if [[ "$answer" != "pass" ]]; then
      ask "$note_var" "   What happened? (one line):" || exit 1
      write_env "$note_var" "${!note_var}"
    fi
  done
}

stage_9() {
  stage "Record the results in ticket 08"
  local titles=(
    "Compose pass A: container healthy and the local administrator signs in"
    "Install from the Template Repositories URL"
    "Healthy container"
    "Bad configuration reported"
    "Local administrator sign-in and OIDC set up in Settings"
    "Library over a private http:// address"
    "Master key separation"
  )
  local i n res note_text saved checks=()
  saved=$(_existing PUBLISH_CHECKS || true)
  [[ -z "$saved" ]] || IFS='|' read -ra checks <<< "$saved"
  say "This adds a dated entry to the ticket's Comments section: the tag, image digest, workflow run,"
  say "the automated checks from stage 7 and your results."
  confirm "Append it to ticket 08?" || return 0
  {
    grep -q '^## Comments' "$TICKET" || printf '\n## Comments\n'
    printf '\n### %s: %s\n\n' "$(date +%F)" "$RELEASE_TAG"
    printf -- '- Image: `%s:%s`%s\n' "$IMAGE" "$RELEASE_TAG" "${IMAGE_DIGEST:+ (digest $IMAGE_DIGEST)}"
    [[ -n "${RUN_URL:-}" ]] && printf -- '- Release workflow: %s\n' "$RUN_URL"
    for note_text in "${checks[@]:-}"; do [[ -n "$note_text" ]] && printf -- '- Check: %s\n' "$note_text"; done
    printf -- '- Unraid checklist:\n'
    for i in "${!titles[@]}"; do
      n=$((i + 1)); res=$(_existing "RESULT_$n" || echo "not recorded"); note_text=$(_existing "NOTE_$n" || true)
      printf '  - %s: **%s**%s\n' "${titles[$i]}" "$res" "${note_text:+ (${note_text})}"
    done
  } >> "$TICKET"
  say "✓ appended to $TICKET"
  note "Commit it, and give anything marked fail or skip to Claude. Ticket 09 repeats this wizard with the stable tag."
}

# Resume support: WIZARD_FROM=8 skips earlier stages, loading what they saved.
FROM="${WIZARD_FROM:-1}"
RELEASE_TAG=$(_existing RELEASE_TAG || true)
EXPORT_DIR=$(_existing EXPORT_DIR || true)
IMAGE_DIGEST=$(_existing IMAGE_DIGEST || true)
RUN_URL=$(_existing RUN_URL || true)
if (( FROM > 1 )) && [[ -z "$RELEASE_TAG" ]]; then
  warn "WIZARD_FROM=$FROM needs a saved release tag; run the wizard from stage 1 first."
  exit 1
fi

banner "Publish a Requestarr release to GitHub and test it on Unraid"

for n in 1 2 3 4 5 6 7 8 9; do
  if (( n < FROM )); then _STAGE_INDEX=$n; continue; fi
  "stage_$n"
done

finish
}

run_wizard "$@"; exit
